// Writes the kana data into components/kakijun/index.js as two generated data blocks (do not edit them by hand), each a
// JSON value between /*@egatari-block <name>*/ and /*@egatari-block-end*/ (Egatari spec §6.2 Subset: a producer keeps only
// the members whose keys, here characters, occur in the lesson; members named _… stay, first):
//   node tools/kana-embed.mjs            regenerate both blocks
//   node tools/kana-embed.mjs --check    both blocks equal what the data files give
//
// stroke-meta (MIT, ours; var KANA): data/kana/kana.json made compact, one character per line:
//   "あ":[count,[[end,len],…]]  or, for small kana, "ぁ":[count,[[end,len],…],{"yoko":[…],"tate":[…]}]  (place)
//   len = the length of the stroke's inked centreline (0–100 units, rounded), so that the part knows each stroke's
//   duration before it draws anything. Notes, sources, base and loop stay in kana.json.
// strokes (SIL OFL 1.1; var STROKES): data/kana/strokes.ofl.json, the stroke shapes derived from strokesvg (Klee One).
//   Studio inlines only a part's index.js (kit/core/build-core.mjs) and an Egatari file records only its sha256, so a part
//   cannot carry a separate data file today. The block holds the file's values: "_license" first, then the file's other
//   top-level fields with a leading "_" (_source, _box, _brush, _format, _derived), then the file's chars, one per line.
//   The OFL notice comment stands directly before the block's marker. OFL.txt, LICENSE-strokesvg.txt and
//   strokes-CHANGES.md are copied into components/kakijun/ next to it.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { inkLine, length } from './kana-svgpath.mjs';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
export const JS = path.join(ROOT, 'components', 'kakijun', 'index.js');
const DATA = path.join(ROOT, 'data', 'kana');
export const LICENSE_FILES = ['OFL.txt', 'LICENSE-strokesvg.txt', 'strokes-CHANGES.md'];

export const BLOCK = (name) => `/*@egatari-block ${name}*/`;
export const BLOCK_END = '/*@egatari-block-end*/';
const DATA_HEAD = '// ---- stroke-meta (MIT; generated by tools/kana-embed.mjs from data/kana/kana.json; do not edit) ----';
// The OFL notice, directly before the strokes block (spec §6.1 Notices: the licence name before the data)
const OFL_NOTICE = '/* OFL-1.1 data: kana stroke shapes derived from strokesvg (Klee One), SIL Open Font License 1.1, NOT under the MIT\n'
  + '   License of the code around it; see OFL.txt, LICENSE-strokesvg.txt and strokes-CHANGES.md in this folder, and "_license" below.\n'
  + '   Generated by tools/kana-embed.mjs from data/kana/strokes.ofl.json; do not edit. */';
const OFL_PRE = 'var STROKES = ';
export const OFL_MARKERS = { notice: OFL_NOTICE.split('\n')[0], begin: BLOCK('strokes'), end: BLOCK_END };

export const inkLength = (pieces) => Math.round(length(inkLine(pieces)));
export function compact(c, shapes) {
  const s = c.strokes.map((x, i) => [x.end, inkLength(shapes[i])]);
  return c.place ? [c.count, s, c.place] : [c.count, s];
}
export function dataBlock(data, ofl) {
  const lines = Object.entries(data.chars).map(([ch, c]) => JSON.stringify(ch) + ':' + JSON.stringify(compact(c, ofl.chars[ch])));
  return [DATA_HEAD, `// ${Object.keys(data.chars).length} characters, data version ${data.version} (order, endings, small-kana placement: original, MIT)`,
    'var KANA = ' + BLOCK('stroke-meta') + '{', lines.join(',\n'), '}' + BLOCK_END + ';'].join('\n');
}
// The OFL file as the strokes block's value: "_license" first, the other top-level fields as _<name>, then the characters
export function strokesValue(ofl) {
  const out = { _license: ofl._license };
  for (const k of Object.keys(ofl)) if (k !== '_license' && k !== 'chars') out['_' + k] = ofl[k];
  return Object.assign(out, ofl.chars);
}
// …and back (for the test: the block must give the file's keys and values)
export function oflOf(value) {
  const o = { _license: value._license }, chars = {};
  for (const [k, v] of Object.entries(value)) { if (k === '_license') continue; if (k.startsWith('_')) o[k.slice(1)] = v; else chars[k] = v; }
  o.chars = chars;
  return o;
}
// The block as written: one field per line
export function shapesJson(ofl) {
  return '{' + Object.entries(strokesValue(ofl)).map(([k, v]) => JSON.stringify(k) + ': ' + JSON.stringify(v)).join(',\n') + '}';
}
export const stringsBlock = (ofl) => OFL_PRE + OFL_NOTICE + '\n' + BLOCK('strokes') + shapesJson(ofl) + BLOCK_END + ';';
// The JSON text of block <name> (exactly one; null if not exactly one pair of markers)
export function blockText(src, name) {
  const b = BLOCK(name), i = src.indexOf(b);
  if (i < 0 || src.indexOf(b, i + 1) >= 0) return null;
  const j = src.indexOf(BLOCK_END, i);
  return j < 0 ? null : src.slice(i + b.length, j);
}
const region = (src, a, name) => {
  const i = src.indexOf(a), k = src.indexOf(BLOCK(name), i), j = src.indexOf(BLOCK_END + ';', k);
  if (i < 0 || k < 0 || j < 0) throw new Error(`${path.relative(ROOT, JS)}: no block ${name}`);
  return [i, j + BLOCK_END.length + 1];
};
// What index.js carries (for tools/test-kakijun.mjs)
export function readEmbedded(src = fs.readFileSync(JS, 'utf8')) {
  const kana = JSON.parse(blockText(src, 'stroke-meta'));
  const inner = blockText(src, 'strokes');
  return {
    kana: Object.fromEntries(Object.entries(kana).map(([ch, a]) => [ch, { count: a[0], strokes: a[1].map(([end, len]) => ({ end, len })), ...(a[2] ? { place: a[2] } : {}) }])),
    strokes: oflOf(JSON.parse(inner)), inner,
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const data = JSON.parse(fs.readFileSync(path.join(DATA, 'kana.json'), 'utf8'));
  const ofl = JSON.parse(fs.readFileSync(path.join(DATA, 'strokes.ofl.json'), 'utf8'));
  let src = fs.readFileSync(JS, 'utf8');
  const errs = [];
  for (const [a, name, want] of [[DATA_HEAD, 'stroke-meta', dataBlock(data, ofl)], [OFL_PRE + OFL_MARKERS.notice, 'strokes', stringsBlock(ofl)]]) {
    const [i, j] = region(src, a, name);
    if (check) { if (src.slice(i, j) !== want) errs.push(`the block ${name} differs from the data (run node tools/kana-embed.mjs)`); }
    else src = src.slice(0, i) + want + src.slice(j);
  }
  for (const f of LICENSE_FILES) {
    const to = path.join(path.dirname(JS), f), from = fs.readFileSync(path.join(DATA, f));
    if (check) { if (!fs.existsSync(to) || !fs.readFileSync(to).equals(from)) errs.push(`components/kakijun/${f} differs from data/kana/${f}`); }
    else fs.writeFileSync(to, from);
  }
  if (errs.length) { errs.forEach((e) => console.log('FAIL ' + e)); process.exit(1); }
  if (!check) fs.writeFileSync(JS, src);
  console.log(`kana-embed${check ? ' --check' : ''}: ${Object.keys(data.chars).length} characters: ok`);
}
